<?php
namespace App\Tests\Runtime;
use App\Runtime\{RuntimeApiEntityActionService,RuntimeExternalJsonClient,RuntimeHttpException};use PHPUnit\Framework\TestCase;
require_once __DIR__.'/RuntimePurchaseItemAuditTest.php';
final class RuntimePurchaseItemOptionsTest extends TestCase {
 private function invoke(string $lookup,array $body,array &$sent,array $delta=[]):array{$d=RuntimePurchaseItemAuditTest::definition();$ep=RuntimePurchaseItemAuditTest::endpoint('options');$ep['bodyTemplate']['lookup']=$lookup;$op=['code'=>'lookup','type'=>'list','path'=>$ep['url'],'itemsPath'=>'data']+array_diff_key($ep,['url'=>1]);$op=array_replace($op,$delta);$d['apiSource']+=['authHeaders'=>[],'operations'=>[$op]];$d['fields']['choice']=['optionsSource'=>['operationCode'=>'lookup','valueField'=>'value','textField'=>'text']];$client=$this->createStub(RuntimeExternalJsonClient::class);$client->method('request')->willReturnCallback(static function($u,$m,$h,$r)use(&$sent,$body){$sent[]=$r;return ['status'=>200,'body'=>$body];});$rc=new \ReflectionClass(RuntimeApiEntityActionService::class);$s=$rc->newInstanceWithoutConstructor();$rc->getProperty('externalJsonClient')->setValue($s,$client);return $rc->getMethod('options')->invoke($s,$d,['fieldCode'=>'choice'],['context'=>['proc_compra_id'=>17]]);}
 public function testAllLookupsKeepFixedBindingAndMandatoryParent():void{foreach(['coloracao','formato_amostra','estacao']as $lookup){$sent=[];$out=$this->invoke($lookup,['success'=>true,'data'=>[['value'=>1,'text'=>'Teste']],'total'=>1],$sent);self::assertSame(['resource'=>'proc_compra_itens','operation'=>'options','lookup'=>$lookup,'proc_compra_id'=>17],$sent[0]);self::assertSame([['value'=>1,'text'=>'Teste']],$out['data']);}}
 public function testUnregisteredLookupAndMalformedOptionEnvelopeAreRejected():void{foreach(['lookup','missing-text','total','duplicate','wrong-type','wrong-context']as $case){$sent=[];$body=['success'=>true,'data'=>[['value'=>1,'text'=>'Teste']],'total'=>1];$delta=[];if($case==='missing-text')unset($body['data'][0]['text']);if($case==='total')$body['total']=2;if($case==='duplicate'){$body['data'][]=$body['data'][0];$body['total']=2;}if($case==='wrong-type')$delta=['type'=>'custom'];if($case==='wrong-context')$delta=['requestContextFields'=>[]];try{$this->invoke($case==='lookup'?'free':'estacao',$body,$sent,$delta);self::fail($case);}catch(RuntimeHttpException $e){self::assertContains($e->getStatusCode(),[422,502]);}}}
}
